// Token/cost estimator: chars/4 heuristic + budget check (plain JS)
function estimateTokens(text) { return Math.ceil(text.length / 4); }
function budgetCheck(parts, budget, pricePer1k) {
  const rows = parts.map((p) => ({ name: p.name, tokens: estimateTokens(p.text) }));
  const total = rows.reduce((s, r) => s + r.tokens, 0);
  return { rows, total, budget, over: total > budget,
    costPer1kCalls: ((total / 1000) * pricePer1k * 1000).toFixed(2) + " $/1k calls" };
}
// budgetCheck([{name:'policy', text}, {name:'ticket', text}], 4000, 0.005)
