// Context assembler: rank, dedupe, position deliberately (plain JS)
function assembleContext(passages, budgetChars) {
  const seen = new Set();
  const ranked = passages
    .filter((p) => p.relevance > 0.2)                       // relevance floor
    .sort((a, b) => b.relevance - a.relevance);
  const picked = [];
  let used = 0;
  for (const p of ranked) {                                 // diversity: skip near-dupes
    const key = p.text.slice(0, 60);
    if (seen.has(key)) continue;
    seen.add(key);
    if (used + p.text.length > budgetChars) break;          // hard budget cap
    picked.push(p);
    used += p.text.length;
  }
  return picked; // caller orders: rules first, evidence last (recency)
}

