function assemble(names, budgetChars) {
  const picked = [];
  let used = 0;
  for (const p of names) {
    if (used + p.text.length > budgetChars) break;
    picked.push(p.name);
    used += p.text.length;
  }
  return { picked, used, tokens: estimateTokens(names.map((p) => p.text).join('').slice(0, used)) };
